import math

def _build_agent_impl(sandbox):
    beams = []

    # Create a horizontal path from x=6 to x=18 at y=2.5
    for i in range(10):
        x = 6.0 + i * 1.2
        y = 2.5
        b = sandbox.add_beam(x, y, 1.2, 0.2, density=50.0)
        sandbox.add_joint(b, None, (x, 0.0), type='rigid')
        beams.append(b)

    # Add vertical supports for the horizontal path
    for x in [6.0, 12.0, 18.0]:
        b = sandbox.add_beam(x, 1.25, 0.2, 2.5, angle=math.pi/2, density=50.0)
        sandbox.add_joint(b, None, (x, 0.0), type='rigid')
        beams.append(b)

    return beams[0]

def build_agent(sandbox):
    return _build_agent_impl(sandbox)

def agent_action(sandbox, agent_body, step_count):
    if not hasattr(sandbox, "get_fluid_particles") or not hasattr(sandbox, "apply_force_to_particle"):
        return

    budget = getattr(sandbox, 'FORCE_BUDGET_PER_STEP', 12000.0)
    particles = sandbox.get_fluid_particles()
    if not particles:
        return

    used = 0.0
    m = 5.0  # Reduced mass parameter to control force magnitude
    g = 10.0  # Standard gravity

    for p in particles:
        if used >= budget:
            break
        x, y = p.position.x, p.position.y
        vx, vy = p.linearVelocity.x, p.linearVelocity.y

        fx, fy = 0.0, 0.0

        # Determine desired direction based on position
        if x < 6.0:
            # Source area: push right and up
            target_vx = 4.0
            target_vy = 2.0
            fx = m * (target_vx - vx)
            fy = m * (target_vy - vy)
        elif 6.0 <= x < 18.0:
            # Path area: follow the horizontal path at y=2.5
            if y < 2.5:
                # Apply upward force
                fy += m * 5.0 * (2.5 - y)
            elif y > 2.5:
                # Apply downward force
                fy -= m * 5.0 * (y - 2.5)
            # Horizontal movement towards target
            target_vx = 5.0
            fx = m * (target_vx - vx)

            # Handle gravity well
            if 10.0 <= x <= 14.0:
                # Apply upward force to counteract gravity well
                fy += m * 3.0
        elif 18.0 <= x < 22.0:
            # Target zone: bring down to y=0-1.5
            if y > 0.2:
                fy = -m * 5.0 * (y - 0.2)
            else:
                # Fine-tuning
                if abs(vx) > 0.2:
                    fx = -m * 10.0 * vx
        else:
            # Beyond target zone: apply gentle force to stay
            fx = -m * 1.0 * vx
            fy = -m * 1.0 * vy

        # Handle headwind (above y=3.0)
        if y > 3.0:
            fx += m * 10.0  # Counteract headwind

        mag = math.sqrt(fx**2 + fy**2)
        if mag > 0:
            if used + mag <= budget:
                sandbox.apply_force_to_particle(p, fx, fy)
                used += mag
            else:
                scale = (budget - used) / mag
                if scale > 0.1:
                    sandbox.apply_force_to_particle(p, fx * scale, fy * scale)
                    used = budget
